SELECT COALESCE(SUM(o.amount), 0)
FROM orders o
WHERE o.status = #{status}
  AND o.order_time >= #{begin}
  AND o.order_time < #{end}
  AND EXISTS (SELECT 1 FROM employee e WHERE e.id = #{employeeId})

